import sympy

def f0(x):
    return x + abs(x - 100) - abs(x + 100)

def fn(x, n):
    if n == 0:
        return f0(x)
    else:
        return abs(fn(x, n - 1))

def count_solutions(n):
    # Create a symbol for x
    x = sympy.symbols('x')

    # Count the number of solutions for f_n(x) = 100
    count = 0
    for i in range(-1000, 1000):
        if abs(fn(i, n)) == 100:
            count += 1

    return count

print(count_solutions(100))
